PRAGMA foreign_keys=ON;
CREATE TABLE readable_file(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,source_path TEXT NOT NULL UNIQUE,source_sha256 TEXT NOT NULL,git_blob TEXT NOT NULL,byte_length INTEGER NOT NULL,encoding TEXT NOT NULL,line_count INTEGER NOT NULL,empty INTEGER NOT NULL CHECK(empty IN(0,1)),body_sha256 TEXT NOT NULL,r0_family TEXT NOT NULL,r0_contract TEXT NOT NULL,r0_run TEXT NOT NULL,r0_occurrence_id TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE readable_line(id TEXT PRIMARY KEY,file_id TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,byte_start INTEGER NOT NULL,byte_end INTEGER NOT NULL,terminator TEXT NOT NULL,raw_text TEXT NOT NULL,text_sha256 TEXT NOT NULL,UNIQUE(file_id,ordinal),FOREIGN KEY(file_id) REFERENCES readable_file(id)) WITHOUT ROWID;
CREATE TABLE readable_relation(id TEXT PRIMARY KEY,origin_family TEXT NOT NULL,origin_contract TEXT,origin_parser TEXT,origin_run TEXT,origin_occurrence_id TEXT NOT NULL,origin_source_path TEXT NOT NULL,origin_pointer TEXT NOT NULL,relation_kind TEXT NOT NULL,raw_locator TEXT NOT NULL,candidate_boundary TEXT NOT NULL,status TEXT NOT NULL,search_complete INTEGER NOT NULL CHECK(search_complete IN(0,1)),candidate_count INTEGER NOT NULL,UNIQUE(origin_family,origin_run,origin_occurrence_id,origin_source_path,origin_pointer,relation_kind,raw_locator)) WITHOUT ROWID;
CREATE TABLE readable_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL,target_file_id TEXT NOT NULL,target_path TEXT NOT NULL,target_r0_occurrence_id TEXT NOT NULL,UNIQUE(relation_id,target_file_id),FOREIGN KEY(relation_id) REFERENCES readable_relation(id),FOREIGN KEY(target_file_id) REFERENCES readable_file(id)) WITHOUT ROWID;
CREATE TABLE readable_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX readable_line_text ON readable_line(raw_text);
CREATE INDEX readable_candidate_target ON readable_candidate(target_file_id,relation_id);
